from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages import v22r3
from taf.selenium.sbts_fsm3.pages.modals import ResetNrOrLte


class BtsBasicInfo(v22r3.BtsBasicInfo):
    _NR_RESET_BUTTON = '//div[div[text()="NR"]]//button'
    _LTE_RESET_BUTTON = '//div[div[text()="LTE"]]//button'

    def __init__(self, driver):
        super(BtsBasicInfo, self).__init__(driver)

    def reset_nr(self, cancel=False, with_graceful=False, timeout=60, with_hard=False):
        self.click_enabled_element((By.XPATH, self._NR_RESET_BUTTON), timeout)
        self._reset(cancel, with_graceful, timeout, with_hard)

    def reset_lte(self, cancel=False, with_graceful=False, timeout=60):
        self.click_enabled_element((By.XPATH, self._LTE_RESET_BUTTON), timeout)
        self._reset(cancel, with_graceful, timeout=timeout)

    def _reset(self, cancel, with_graceful=False, timeout=60, with_hard=False):
        reset_nr_or_lte_modal = ResetNrOrLte(self.driver)
        reset_nr_or_lte_modal.wait_until_reset_modal_appear(timeout)
        if cancel:
            reset_nr_or_lte_modal.cancel(timeout)
        else:
            reset_nr_or_lte_modal.reset(with_graceful, timeout, with_hard)
